mapper.update:
UPDATE TB_LNK_PARTNER
   SET CSS_ENGINE = #{cssEngine}, PRODUCTS = #{products}, TIMEOUT_MS = #{timeoutMs}, MARGIN_MS = #{marginMs},
       ALLOW_IPS = #{allowIps}, USE_YN = #{useYn}, UPD_AT = #{updAt}, UPD_BY = #{updBy}
 WHERE PARTNER_CD = #{partnerCd}

UPDATE TB_LNK_LIMIT_REQ
   SET CSS_PRODUCT = #{cssProduct}, CSS_ENGINE = #{cssEngine}, STATUS = #{status}, RESULT_CD = #{resultCd}, OUTER_CD = #{outerCd},
       LIMIT_AMT = #{limitAmt}, RATE_BP = #{rateBp}, CSS_TX_NO = #{cssTxNo}, CSS_MS = #{cssMs}, TOTAL_MS = #{totalMs},
       SHADOW_RESULT = #{shadowResult}, RES_BODY = #{resBody}, RES_AT = #{resAt}
 WHERE LNK_REQ_NO = #{lnkReqNo}

mapper.select:
SELECT , p.PARTNER_NM, p.TIMEOUT_MS
  FROM TB_LNK_LIMIT_REQ r
  LEFT JOIN TB_LNK_PARTNER p ON p.PARTNER_CD = r.PARTNER_CD

    AND r.PARTNER_CD = #{partnerCd}
    AND r.STATUS = #{status}
    AND r.RESULT_CD = #{resultCd}

 ORDER BY r.REQ_AT DESC
 LIMIT #{limit}
